        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        int Q = Integer.parseInt(line.trim());

        List<Long> stack = new ArrayList<>();
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < Q; i++) {
            line = br.readLine();
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) continue;
            String cmd = st.nextToken();
            if (cmd.equals("push")) {
                stack.add(Long.parseLong(st.nextToken()));
            } else if (cmd.equals("pop")) {
                if (stack.isEmpty()) sb.append("-1\n");
                else sb.append(stack.remove(stack.size() - 1)).append("\n");
            } else if (cmd.equals("peek")) {
                if (stack.isEmpty()) sb.append("-1\n");
                else sb.append(stack.get(stack.size() - 1)).append("\n");
            } else if (cmd.equals("size")) {
                sb.append(stack.size()).append("\n");
            } else if (cmd.equals("isEmpty")) {
                sb.append(stack.isEmpty() ? "1\n" : "0\n");
            }
        }
        System.out.print(sb.toString());
    }
}

