                if (top1 >= 0) {
                    sb.append(arr[top1--]).append("\n");
                } else {
                    sb.append("-1\n");
                }
            } else if (cmd.equals("pop2")) {
                if (top2 < N) {
                    sb.append(arr[top2++]).append("\n");
                } else {
                    sb.append("-1\n");
                }
            }
