#include <iostream>
#include <string>

using namespace std;

struct Node {
    long long val;
    Node* prev;
    Node* next;
    Node(long long v) : val(v), prev(nullptr), next(nullptr) {}
};

class MidStack {
    Node* head;
    Node* mid;
    int count;
public:
    MidStack() : head(nullptr), mid(nullptr), count(0) {}

    void push(long long val) {
        Node* node = new Node(val);
        node->next = head;
        count++;
        if (count == 1) {
            head = node;
            mid = node;
        } else {
            head->prev = node;
            head = node;
            if (count % 2 != 0) mid = mid->prev;
        }
    }

    long long pop() {
        if (count == 0) return -1;
        long long val = head->val;
        Node* temp = head;
        head = head->next;
        if (head) head->prev = nullptr;
        delete temp;
        count--;
        if (count == 0) mid = nullptr;
        else if (count % 2 == 0) mid = mid->next;
        return val;
    }

    long long getMid() {
        if (count == 0 || !mid) return -1;
        return mid->val;
    }

    long long delMid() {
        if (count == 0 || !mid) return -1;
        long long val = mid->val;
        if (count == 1) {
            delete mid;
            head = nullptr; mid = nullptr; count = 0;
            return val;
        }
        Node* p = mid->prev;
        Node* n = mid->next;
        if (p) p->next = n;
        if (n) n->prev = p;
        if (mid == head) head = n;
        delete mid;
        count--;
        if (count % 2 != 0) mid = p;
        else mid = n;
        return val;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int Q;
    if (!(cin >> Q)) return 0;

    MidStack st;
    while (Q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "push") {
            long long x; cin >> x;
            st.push(x);
        } else if (cmd == "pop") {
            cout << st.pop() << "\n";
        } else if (cmd == "getMid") {
            cout << st.getMid() << "\n";
        } else if (cmd == "delMid") {
            cout << st.delMid() << "\n";
        }
    }
    return 0;
}

