import sys

def precedence(op):
    if op in ('+', '-'):
        return 1
    if op in ('*', '/'):
        return 2
    return 0

def apply_op(a, b, op):
    if op == '+': return a + b
    if op == '-': return a - b
    if op == '*': return a * b
    if op == '/':
        # Truncate towards zero
        return int(a / b)
    return 0

def solve():
    raw = sys.stdin.read().strip()
    if not raw:
        return

    values = []
    ops = []
    i = 0
    N = len(raw)

    while i < N:
        if raw[i] == ' ':
            i += 1
            continue
        elif raw[i] == '(':
            ops.append(raw[i])
            i += 1
        elif raw[i].isdigit():
            val = 0
            while i < N and raw[i].isdigit():
                val = val * 10 + int(raw[i])
                i += 1
            values.append(val)
        elif raw[i] == ')':
            while ops and ops[-1] != '(':
                op = ops.pop()
                b = values.pop()
                a = values.pop()
                values.append(apply_op(a, b, op))
            if ops:
                ops.pop() # pop '('
            i += 1
        else: # operator
            while ops and ops[-1] != '(' and precedence(ops[-1]) >= precedence(raw[i]):
                op = ops.pop()
                b = values.pop()
                a = values.pop()
                values.append(apply_op(a, b, op))
            ops.append(raw[i])
            i += 1

    while ops:
        op = ops.pop()
        b = values.pop()
        a = values.pop()
        values.append(apply_op(a, b, op))

    print(values[-1])

if __name__ == '__main__':
