from collections import deque

class QueueStack:
    def __init__(self):
        self.q = deque()

    def push(self, x):
        self.q.append(x)
        # Rotate previous elements to make x the front of the queue
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())

    def pop(self):
        if not self.q:
            return -1
        return self.q.popleft()

    def top(self):
        if not self.q:
            return -1
        return self.q[0]

    def size(self):
        return len(self.q)

    def isEmpty(self):
        return 1 if not self.q else 0

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    Q = int(lines[0].strip())

    st = QueueStack()
    out = []

