import sys

class StackQueue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def enqueue(self, x):
        self.in_stack.append(x)

    def _shift(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def dequeue(self):
        self._shift()
        if not self.out_stack:
            return -1
        return self.out_stack.pop()

    def front(self):
        self._shift()
        if not self.out_stack:
            return -1
        return self.out_stack[-1]

    def size(self):
        return len(self.in_stack) + len(self.out_stack)

    def isEmpty(self):
        return 1 if self.size() == 0 else 0

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    Q = int(lines[0].strip())

    q = StackQueue()
    out = []

    for i in range(1, Q + 1):
        if i >= len(lines):
            break
        parts = lines[i].strip().split()
