import sys

class CircularQueue:
    def __init__(self, k):
        self.k = k
        self.arr = [0] * k
        self.head = 0
        self.count = 0

    def enQueue(self, val):
        if self.count == self.k:
            return -1
        tail = (self.head + self.count) % self.k
        self.arr[tail] = val
        self.count += 1
        return 1

    def deQueue(self):
        if self.count == 0:
            return -1
        self.head = (self.head + 1) % self.k
        self.count -= 1
        return 1

    def Front(self):
        if self.count == 0:
            return -1
        return self.arr[self.head]

    def Rear(self):
        if self.count == 0:
            return -1
        tail = (self.head + self.count - 1) % self.k
        return self.arr[tail]

    def isEmpty(self):
        return 1 if self.count == 0 else 0

    def isFull(self):
        return 1 if self.count == self.k else 0

