public class Main {
    static class TreeNode {
        long val;
        TreeNode left, right;
        TreeNode(long val) { this.val = val; }
    }

    static TreeNode buildTree(String[] tokens) {
        if (tokens.length == 0 || tokens[0].equals("null") || tokens[0].isEmpty()) return null;
        TreeNode root = new TreeNode(Long.parseLong(tokens[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int idx = 1;
        while (!q.isEmpty() && idx < tokens.length) {
            TreeNode node = q.poll();
            if (idx < tokens.length && !tokens[idx].equals("null")) {
                node.left = new TreeNode(Long.parseLong(tokens[idx]));
                q.add(node.left);
            }
            idx++;
            if (idx < tokens.length && !tokens[idx].equals("null")) {
                node.right = new TreeNode(Long.parseLong(tokens[idx]));
                q.add(node.right);
            }
            idx++;
        }
        return root;
    }

    static List<List<Long>> getLevels(TreeNode root) {
        List<List<Long>> levels = new ArrayList<>();
        if (root == null) return levels;
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        while (!q.isEmpty()) {
            int sz = q.size();
            List<Long> lvl = new ArrayList<>();
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                lvl.add(node.val);
                if (node.left != null) q.add(node.left);
                if (node.right != null) q.add(node.right);
            }
            Collections.sort(lvl);
            levels.add(lvl);
        }
        return levels;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line1 = sc.hasNextLine() ? sc.nextLine().trim() : "";
        String line2 = sc.hasNextLine() ? sc.nextLine().trim() : "";

        String[] t1 = line1.isEmpty() ? new String[0] : line1.split("\\s+");
        String[] t2 = line2.isEmpty() ? new String[0] : line2.split("\\s+");

        TreeNode r1 = buildTree(t1);
        TreeNode r2 = buildTree(t2);

        List<List<Long>> l1 = getLevels(r1);
        List<List<Long>> l2 = getLevels(r2);

        System.out.println(l1.equals(l2) ? 1 : 0);
    }
}

