        if (idx < tokens.size() && tokens[idx] != "null") {
            node->left = new TreeNode(stoll(tokens[idx]));
            q.push(node->left);
        }
        idx++;
        if (idx < tokens.size() && tokens[idx] != "null") {
            node->right = new TreeNode(stoll(tokens[idx]));
            q.push(node->right);
        }
        idx++;
    }
