        String S = sc.next();

        int[] freq = new int[26];
        ArrayDeque<Character> q = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();

        for (char ch : S.toCharArray()) {
            freq[ch - 'a']++;
            q.add(ch);

            while (!q.isEmpty() && freq[q.peek() - 'a'] > 1) {
                q.poll();
            }
            if (!q.isEmpty()) sb.append(q.peek());
            else sb.append('#');
        }
        System.out.println(sb.toString());
    }
}

